#pragma once
#include "AnimationResourceContracts.hpp"
#include <Workphone/System/RigResourceCompiler.hpp>
#include <Workphone/System/RetargetResourceCompiler.hpp>

namespace rig_resource_contracts
{
    using namespace workphone;using namespace workphone::resource;
    inline const char *chain(){return R"(<skeleton><bones><bone id="0" name="Root"/><bone id="1" name="Mid"><position x="1" y="0" z="0"/></bone><bone id="2" name="Hand"><position x="1" y="0" z="0"/></bone></bones><bonehierarchy><boneparent bone="Mid" parent="Root"/><boneparent bone="Hand" parent="Mid"/></bonehierarchy><animations><animation name="Idle" length="1"><tracks><track bone="Root" handle="0"><keyframes><keyframe time="0"><translate x="0" y="0" z="0"/></keyframe><keyframe time="1"><translate x="0" y="0" z="0"/></keyframe></keyframes></track><track bone="Mid" handle="1"><keyframes><keyframe time="0"><translate x="1" y="0" z="0"/></keyframe><keyframe time="1"><translate x="1" y="0" z="0"/></keyframe></keyframes></track><track bone="Hand" handle="2"><keyframes><keyframe time="0"><translate x="1" y="0" z="0"/></keyframe><keyframe time="1"><translate x="1" y="0" z="0"/></keyframe></keyframes></track></tracks></animation></animations></skeleton>)";}
    inline String recipe(const char *base="data://motion.agraph"){return String(R"({"version":1,"animation":")")+base+R"(","constraints":[{"id":"Reach","effector":"Hand","targetPosition":[1,1,0],"targetRotation":[1,0,0,0],"pole":[0,0,1],"weight":1,"chainRotationWeight":0,"blendMode":"effector","matchTargetOrientation":false,"enabled":true}]})";}
    inline String changed(String value,const String &from,const String &to){const auto at=value.find(from);BOOST_REQUIRE(at!=String::npos);value.replace(at,from.size(),to);return value;}
    inline Vector3<real_Num> hand(scene::Animator &animator){Transform3<real_Num> result;BOOST_REQUIRE(animation::TwoBoneIKSolver::getModelSpaceTransform(animator.getSkeleton()->getBone("Hand"),result));return result.getPosition();}
}

BOOST_AUTO_TEST_CASE(typed_native_two_bone_rig_source_free_owner_contract)
{
    using namespace rig_resource_contracts;namespace fs=std::filesystem;
    const auto parent=fs::temp_directory_path(),folder=parent/fs::u8path(("wp-ikrig-family-"+StringUtil::getUUID()).c_str());fs::create_directories(folder/"source");fs::create_directories(folder/"package"/"artifacts"/"v2");
    struct Cleanup{fs::path parent,folder;~Cleanup(){std::error_code ignored;if(folder.parent_path()==parent&&folder.filename().u8string().find("wp-ikrig-family-")==0)fs::remove_all(folder,ignored);}} cleanup{parent,folder};
    animation_resource_contracts::save(folder/"source"/"rig.skelres",chain());animation_resource_contracts::save(folder/"source"/"target.skelres",chain());
    animation_resource_contracts::save(folder/"source"/"motion.agraph",R"({"version":1,"rig":"data://rig.skelres","initialState":"Idle","clips":[{"id":"idle","clip":"Idle","speed":1,"loop":true}],"parameters":[],"states":[{"id":"Idle","clip":"idle","speed":1}],"transitions":[]})");
    animation_resource_contracts::save(folder/"source"/"transfer.aretgt",R"({"version":1,"source":"data://rig.skelres","target":"data://target.skelres","clips":[{"source":"Idle","target":"Transferred"}],"bones":[{"source":"Root","target":"Root","translationScale":1},{"source":"Mid","target":"Mid","translationScale":1},{"source":"Hand","target":"Hand","translationScale":1}]})");
    animation_resource_contracts::save(folder/"source"/"reach.arig",recipe());animation_resource_contracts::save(folder/"source"/"direct.arig",recipe("data://rig.skelres"));animation_resource_contracts::save(folder/"source"/"transferred.arig",recipe("data://transfer.aretgt"));
    ResourceCompilerRegistry registry;String error;BOOST_REQUIRE(registry.registerCompiler(std::make_shared<SkeletonResourceCompiler>(),&error));BOOST_REQUIRE(registry.registerCompiler(std::make_shared<AnimationResourceCompiler>(),&error));BOOST_REQUIRE(registry.registerCompiler(std::make_shared<RetargetResourceCompiler>(),&error));BOOST_REQUIRE(registry.registerCompiler(std::make_shared<RigResourceCompiler>(),&error));
    std::map<String,String> artifacts;std::map<String,CompiledResourceHeader> headers;
    auto cook=[&](const String &id,const char *leaf){CompileContext context;context.resourceId=ResourceID(id);context.sourcePath=(folder/"source"/leaf).u8string().c_str();context.compiledRoot=(folder/"package").u8string().c_str();context.target="pc";context.packagedBuild=true;const auto compiler=registry.getCompiler(context.resourceId.type());BOOST_REQUIRE(compiler);DependencySet dependencies;const bool scanned=compiler->getDependencies(context,dependencies,error);BOOST_REQUIRE_MESSAGE(scanned,error.c_str());
        for(const auto &dependency:dependencies.compileDependencies)if(dependency.isResource)context.dependencyArtifacts[dependency.path]=artifacts.at(dependency.path);
        std::ostringstream output;Array<String> messages;const auto status=compiler->compile(context,output,messages);BOOST_REQUIRE_MESSAGE(status==CompilationStatus::Success,(messages.empty()?"Typed IK rig cook failed":messages.front().c_str()));const auto bytes=output.str();const auto payload=folder/"package"/"temporary.payload";{std::ofstream file(payload,std::ios::binary);file.write(bytes.data(),bytes.size());BOOST_REQUIRE(bool(file));}
        CompiledResourceHeader header;header.formatVersion=2;header.resourceId=context.resourceId;header.resourceType=context.resourceId.type();header.compilerVersion=compiler->versionFor(header.resourceType);header.sourceHash=1;header.payloadSize=bytes.size();header.payloadHash=hashBytes(bytes.data(),bytes.size());header.installDependencies=dependencies.installDependencies;
        for(const auto &dependency:header.installDependencies){const auto &pin=headers.at(dependency.str());header.installArtifacts.push_back({"artifacts/v2/"+String(fs::u8path(artifacts.at(dependency.str()).c_str()).filename().u8string().c_str()),pin.sourceHash,pin.payloadHash});}
        const auto artifact=folder/"package"/"artifacts"/"v2"/(std::string(leaf)+".wprc");const bool written=CompiledResourceIO::writeAtomic(artifact.u8string().c_str(),header,payload.u8string().c_str(),error);BOOST_REQUIRE_MESSAGE(written,error.c_str());fs::remove(payload);artifacts[id]=artifact.u8string().c_str();headers[id]=header;};
    cook("data://rig.skelres","rig.skelres");cook("data://target.skelres","target.skelres");cook("data://motion.agraph","motion.agraph");cook("data://transfer.aretgt","transfer.aretgt");cook("data://reach.arig","reach.arig");cook("data://direct.arig","direct.arig");cook("data://transferred.arig","transferred.arig");
    RigResourceCompiler compiler;CompileContext bad;bad.resourceId=ResourceID("data://bad.arig");bad.sourcePath=(folder/"source"/"bad.arig").u8string().c_str();bad.compiledRoot=(folder/"package").u8string().c_str();bad.dependencyArtifacts["data://motion.agraph"]=artifacts.at("data://motion.agraph");
    auto reject=[&](const String &value,bool scan){animation_resource_contracts::save(folder/"source"/"bad.arig",value);DependencySet dependencies;if(scan)BOOST_CHECK(!compiler.getDependencies(bad,dependencies,error));else{std::ostringstream out;Array<String> messages;BOOST_CHECK(compiler.compile(bad,out,messages)==CompilationStatus::Failure);}};
    reject(changed(recipe(),"\"version\":1","\"version\":1,\"humanoid\":true"),true);reject(recipe("data://recursive.arig"),true);reject(changed(recipe(),"\"weight\":1","\"weight\":-1"),true);reject(changed(recipe(),"\"targetRotation\":[1,0,0,0]","\"targetRotation\":[0,0,0,0]"),true);reject(changed(recipe(),"\"blendMode\":\"effector\"","\"blendMode\":\"unknown\""),true);reject(changed(recipe(),"\"effector\":\"Hand\"","\"effector\":\"Missing\""),false);reject(changed(recipe(),"\"effector\":\"Hand\"","\"effector\":\"Mid\""),false);
    reject(changed(recipe(),"\"targetPosition\":[1,1,0]","\"targetPosition\":[1e400,1,0]"),true);
    auto duplicate=recipe();const auto entry=duplicate.find("{\"id\""),end=duplicate.rfind("}]");const auto copied=duplicate.substr(entry,end+1-entry);duplicate.insert(end+1,","+copied);reject(duplicate,true);
    fs::remove_all(folder/"source");
    std::map<String,std::shared_ptr<const RuntimeResource>> loaded;std::function<std::shared_ptr<const RuntimeResource>(const String &)> read=[&](const String &id){const auto known=loaded.find(id);if(known!=loaded.end())return known->second;auto value=std::make_shared<RuntimeResource>();const bool decoded=CompiledResourceIO::read(artifacts.at(id),*value,error,2u<<20);BOOST_REQUIRE_MESSAGE(decoded,error.c_str());for(const auto &child:value->header.installDependencies)value->dependencies.push_back(read(child.str()));loaded[id]=value;return std::shared_ptr<const RuntimeResource>(value);};
    const auto resource=read("data://reach.arig");BOOST_CHECK_EQUAL(std::memcmp(resource->payload.data(),"WPIK",4),0);ResourceID animation;BOOST_REQUIRE(RigResourceCompiler::animationIdentity(*resource,animation,error));BOOST_CHECK(animation==ResourceID("data://motion.agraph"));
    const String uuid="9ae4ad1d-a23a-40c9-9b68-eb74bbcb5732";auto context=std::make_shared<RuntimeAssetContext>();context->resolve=[resource,uuid](const String &id,String &failure)->std::shared_ptr<const RuntimeResource>{if(id==uuid)return resource;failure="Unbound native IK rig UUID";return {};};
    scene::Animator first,second;first.configureRuntimeAssets(context);second.configureRuntimeAssets(context);auto properties=make_ptr<Properties>();properties->setProperty("animationAssetUuid",uuid);first.setProperties(properties);second.setProperties(properties);
    BOOST_REQUIRE(first.getSkeleton()!=second.getSkeleton());BOOST_REQUIRE(first.hasAnimationGraph()&&second.hasAnimationGraph());BOOST_REQUIRE_EQUAL(first.getIKSystem().getConstraints().size(),1u);BOOST_REQUIRE_EQUAL(first.getLastIKSolveResults().size(),1u);BOOST_CHECK(first.getLastIKSolveResults()[0].result.success);
    const auto initial=hand(first);BOOST_CHECK_SMALL(initial.X()-1,.001f);BOOST_CHECK_SMALL(initial.Y()-1,.001f);BOOST_CHECK_SMALL(initial.Z(),.001f);
    Transform3<real_Num> target(Vector3<real_Num>(0,1,1),Quaternion<real_Num>::identity());BOOST_REQUIRE(first.getIKSystem().setTarget("Reach",target));first.setAnimationTime(.5f);const auto changedPose=hand(first),otherPose=hand(second);BOOST_CHECK_SMALL(changedPose.X(),.001f);BOOST_CHECK_SMALL(changedPose.Y()-1,.001f);BOOST_CHECK_SMALL(changedPose.Z()-1,.001f);BOOST_CHECK_SMALL(otherPose.X()-1,.001f);BOOST_CHECK_SMALL(otherPose.Y()-1,.001f);
    for(const auto &id:{String("data://direct.arig"),String("data://transferred.arig")}){scene::Animator native;const bool installed=native.loadResource(read(id),error);BOOST_REQUIRE_MESSAGE(installed,error.c_str());native.setAnimationTime(.5f);const auto pose=hand(native);BOOST_CHECK_SMALL(pose.X()-1,.001f);BOOST_CHECK_SMALL(pose.Y()-1,.001f);BOOST_REQUIRE_EQUAL(native.getLastIKSolveResults().size(),1u);BOOST_CHECK(native.getLastIKSolveResults()[0].result.success);native.unload(nullptr);}
    const auto previous=first.getSkeleton();auto broken=std::make_shared<RuntimeResource>(*resource);broken->payload.back()^=1;BOOST_CHECK(!first.loadResource(broken,error));BOOST_CHECK(first.getSkeleton()==previous);
    broken=std::make_shared<RuntimeResource>(*resource);broken->payload[4]=2;animation_resource_contracts::seal(*broken);BOOST_CHECK(!first.loadResource(broken,error));BOOST_CHECK(first.getSkeleton()==previous);
    broken=std::make_shared<RuntimeResource>(*resource);++broken->header.installArtifacts[0].sourceHash;BOOST_CHECK(!first.loadResource(broken,error));BOOST_CHECK(first.getSkeleton()==previous);
    broken=std::make_shared<RuntimeResource>(*resource);const u32 nan=0x7fc00000;std::memcpy(broken->payload.data()+broken->payload.size()-16,&nan,4);animation_resource_contracts::seal(*broken);BOOST_CHECK(!first.loadResource(broken,error));BOOST_CHECK(first.getSkeleton()==previous);
    auto scheduler=WorldStreamingScheduler::shared();const auto category=size_t(StreamMemoryClass::SourceCpu),limit=scheduler->stats().limits[category];struct Restore{std::shared_ptr<WorldStreamingScheduler> scheduler;u64 limit;~Restore(){String ignored;scheduler->setBudget(StreamMemoryClass::SourceCpu,limit,ignored);}} restore{scheduler,limit};BOOST_REQUIRE(scheduler->setBudget(StreamMemoryClass::SourceCpu,scheduler->stats().used[category],error));BOOST_CHECK(!first.loadResource(resource,error));BOOST_CHECK(first.getSkeleton()==previous);BOOST_REQUIRE(scheduler->setBudget(StreamMemoryClass::SourceCpu,limit,error));BOOST_CHECK(first.getIKSystem().findConstraint("Reach")->targetTransform.getPosition()==target.getPosition());
    first.clearAnimationGraph();const auto plain=read("data://rig.skelres");BOOST_REQUIRE(first.loadResource(plain,error));BOOST_CHECK(first.getIKSystem().getConstraints().empty());
    first.unload(nullptr);second.unload(nullptr);BOOST_CHECK(!first.getSkeleton()&&!second.getSkeleton());
}
